'use strict';
const C=StudioCore,D=STUDIO_DATA;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>/^https:\/\//.test(u||'')?u:'#';
const readStore=(k,def)=>{try{return JSON.parse(localStorage.getItem(k))??def;}catch{return def;}};
const writeStore=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{toast('Browser storage unavailable; export your work to retain it.',true);return false;}};
let locale=readStore('openstudio:language','zh');if(!D.locales[locale])locale='zh';
let reading=readStore('openstudio:reading',['zh','vi'].includes(locale)?locale:'en'),user=null,csrf=null,hasServer=false,sessionReady=false;
let selected=[],progress={quizzes:{},readings:{}},projects=[],project=C.newProject(),lastRun=null,activeLab='alignment',repoQuery='',repoArea='',repoFeatured=false,repoLicensed=false,repoLevel=1,repoLimit=24;
let libraryQuery='',libraryTab='sources',classCourses=[],submissions={},currentCourse='';
const t=k=>D.locales[locale][k]||D.locales.en[k]||k;
const x=(zh,en)=>locale==='zh'?zh:en;
const local=o=>typeof o==='string'?o:(o?.[locale]||o?.en||o?.zh||'');
const content=o=>o?.[reading]||o?.en||o?.zh||'';
const key=()=> 'openstudio:v1:'+(user?'user:'+user.id:'offline');
function restore(){const state=readStore(key(),{});selected=Array.isArray(state.selected)?state.selected.slice(0,6):[];progress=state.progress||{quizzes:{},readings:{}};progress.quizzes||={};progress.readings||={};projects=[];for(const p of state.projects||[]){try{projects.push(C.validateProject(p));}catch{}}try{if(state.project){const title=state.project.title||'';project=C.validateProject({...state.project,title:title||'Draft'});project.title=title;}else project=C.newProject();}catch{project=C.newProject();}project.locale=locale;}
function persist(){return writeStore(key(),{selected,progress,projects,project});}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='toast'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.className='';el.textContent='';},5000);}
function go(hash){closeModal();location.hash=hash;if(location.hash.replace('#','')===hash)render();}
function button(text,action,cls='',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function pill(s,cls=''){return `<span class="pill ${cls}">${esc(s)}</span>`;}
function tagName(tag){const pair={purpose:['目的','Purpose'],education:['教育','Education'],language:['跨语言','Languages'],evidence:['证据','Evidence'],mathematics:['语义数学','Mathematics'],health:['健康','Health'],economy:['经济','Economy'],memory:['记忆','Memory'],consciousness:['人工意识','Consciousness'],security:['安全','Security'],industry:['行业','Industry'],innovation:['创新','Innovation']}[tag]||[tag,tag];return x(...pair);}
function tags(tags_){return `<div class="tags">${tags_.map(tag=>pill(tagName(tag))).join('')}</div>`;}
function refs(ids){return ids.map(id=>{const s=D.sources.find(s=>s.id===id);return s?`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(id)}</a>`:'';}).join(' · ');}
function header(){const nav=['home','learn','compass','labs','studio','classroom','library'],page=(location.hash.slice(1).split('/')[0]||'home');return `<div class="layout"><aside class="sidebar"><div class="brandmark"><div class="brandicon">DK</div><div><div class="brandtitle">${x('知行共创','OpenStudio')}</div><div class="brandsub">DIKWP · ASEAN</div></div></div><nav class="nav">${nav.map((v,i)=>button(`<span class="num">0${i+1}</span><span>${esc(t(v))}</span>`,'nav',v===page?'active':'',`data-to="${v}"`)).join('')}</nav><div class="sidebar-bottom"><div class="line"></div><strong>Yucong Duan · 段玉聪</strong>DIKWP · Semantic Mathematics<br>Artificial Consciousness<p style="margin-top:14px">${x('让原创方法，成为每个人<br>能够进入的创造空间。','Original methods.<br>Open paths to creation.')}</p><span class="pill">v1.0.0 · Apache-2.0</span></div></aside><div class="shell"><header class="topbar"><div class="topbar-title">${esc(local(D.site.audience))}</div><div class="topbar-actions"><span class="smalltext"><span class="status-dot"></span>${esc(user?user.username:t('offline'))}</span><select id="locale" aria-label="Interface language">${Object.entries(D.locales).map(([k,l])=>`<option value="${k}" ${k===locale?'selected':''}>${esc(l.name)}</option>`).join('')}</select>${button(esc(user?t('account'):t('login')),'nav','small',`data-to="classroom"`)}</div></header><main class="main" id="main" tabindex="-1"></main></div></div>`;}
function footer(){return `<footer class="footer"><span>DIKWP OpenStudio · ${x('研究方法：段玉聪 Yucong Duan','Research foundations: Yucong Duan')} · 2026</span><span>${x('学习 · 选择 · 实践 · 继承 · 创新','Learn · Select · Experiment · Inherit · Create')}</span></footer>`;}
function svg(){return `<svg viewBox="0 0 380 330" role="img" aria-label="DIKWP semantic network"><circle cx="190" cy="167" r="123" fill="none" stroke="#8db299" stroke-opacity=".4"/><circle cx="190" cy="167" r="85" fill="none" stroke="#8db299" stroke-opacity=".2"/><path d="M190 44 L307 129 L262 267 L118 267 L73 129 Z M190 44 L262 267 L73 129 L307 129 L118 267 Z" fill="none" stroke="#a7c3a9" stroke-opacity=".5"/>${[[190,44,'D'],[307,129,'I'],[262,267,'K'],[118,267,'W'],[73,129,'P']].map(([cx,cy,l],i)=>`<circle cx="${cx}" cy="${cy}" r="24" fill="${i===4?'#e8cf9b':'#286b55'}" stroke="#91b79b"/><text x="${cx}" y="${cy+6}" text-anchor="middle" fill="${i===4?'#1b4734':'#fff'}" font-size="18" font-family="sans-serif" font-weight="600">${l}</text>`).join('')}<circle cx="190" cy="167" r="38" fill="#ecdbb5"/><text x="190" y="163" text-anchor="middle" fill="#174731" font-size="11" font-weight="700">YOUR</text><text x="190" y="180" text-anchor="middle" fill="#174731" font-size="11" font-weight="700">QUESTION</text></svg>`;}
function home(){return `<section class="hero"><div><div class="eyebrow">YUCONG DUAN · OPEN RESEARCH COMMONS</div><h1>${esc(t('tagline'))}</h1><p>${esc(t('description'))}</p><div class="row">${button(esc(t('start'))+' ↗','nav','primary','data-to="learn"')}${button(esc(t('explore')),'nav','ghost','data-to="compass"')}</div><div class="pathline">${['learn','compass','labs','studio'].map((v,i)=>`<div class="pathstep"><b>0${i+1}</b><span>${esc(t(v))}</span></div>`).join('')}</div></div><div class="hero-art">${svg()}</div></section><div class="grid four">${[[D.catalog.repositories.length,x('带来源的仓库学习入口','Traceable repository entries')],[12,x('问题驱动学习单元','Question-led learning modules')],[4,x('可改、可运行的教学实验','Editable, runnable teaching labs')],[13,x('界面与核心术语语言','Interface & core-term languages')]].map(([n,label])=>`<div class="card stat"><div class="value">${n}<span style="color:#c9d9c9"> /</span></div><div class="caption">${label}</div></div>`).join('')}</div><section class="section-space"><div class="section-head"><div><div class="eyebrow">START WITH A REAL QUESTION</div><h2>${x('你的问题，就是研究的起点。','Your question is the starting point.')}</h2></div>${button(esc(t('create'))+' ↗','new','small')}</div><div class="grid three">${D.scenarios.map((s,i)=>`<article class="card scenario"><div class="index">0${i+1}</div><h3>${esc(local(s.title))}</h3><p>${esc(local(s.problem))}</p>${tags(s.tags.slice(0,3))}${button(esc(t('start'))+' →','scenario','small',`data-id="${s.id}"`)}</article>`).join('')}</div></section><section class="section-space card"><div class="row between"><div><div class="eyebrow">FROM THE LECTURE TO YOUR WORK</div><h2>${x('报告不止于听懂，学习不止于收藏。','Turn a lecture into a research practice.')}</h2><p class="muted">${x('配套原128页报告与107条来源索引。把一个概念带入实验，再把结果带回你自己的作品。','Explore the 128-page companion report and 107 source entries. Take a concept into an experiment, then bring the result into your own project.')}</p></div>${button(esc(t('report'))+' →','report')}</div></section>`;}
function learn(id){const l=D.lessons.find(v=>v.id===id)||D.lessons[0];const correct=Object.values(progress.quizzes).filter(v=>v.correct).length;
return `<div class="section-title"><div class="eyebrow">LEARNING ATLAS · BUILD UNDERSTANDING</div><h2>${esc(t('learn'))}</h2><div class="row between"><p>${x('从问题、案例与反例进入方法；自测记录理解，实验检验变化。','Enter each method through a question, example and counterexample. Use self-checks and experiments to examine understanding.')}</p><div class="row"><span class="readlang">${t('reading')}:</span><select id="reading"><option value="zh" ${reading==='zh'?'selected':''}>中文</option><option value="en" ${reading==='en'?'selected':''}>English</option><option value="vi" ${reading==='vi'?'selected':''}>Tiếng Việt</option></select></div></div><div class="coverage">${x('13语种导航与术语桥；完整深度讲义及自测提供中文、英文、越南语。原始论文与仓库保留原文。','13-language navigation and terminology bridge. Full lessons and quizzes are available in Chinese, English and Vietnamese; original sources keep their original language.')}</div></div><div class="study-grid"><aside class="lesson-menu">${D.lessons.map((a,i)=>button(`<small>${String(i+1).padStart(2,'0')} ${progress.quizzes[a.id]?.correct?'✓':''}</small>${esc(local(a.title))}`,'lesson',a.id===l.id?'active':'',`data-id="${a.id}"`)).join('')}<div class="card cardsmall"><div class="smalltext">${t('progress')} ${correct}/12</div><div class="progressbar"><span style="width:${correct/12*100}%"></span></div><div class="note">${x('答对单题表示本次自测通过，不是能力认证。','A correct answer records this self-check, not a competence certificate.')}</div></div></aside><article class="card lesson-body"><div class="eyebrow">${l.id.toUpperCase()} · DIKWP METHOD</div><h2>${esc(content(l.title))}</h2><p><strong>${esc(content(l.question))}</strong></p><p>${esc(content(l.body))}</p><h3>${x('看一个具体例子','A worked example')}</h3><div class="example">${esc(content(l.example))}</div><h3>${x('辨别一个常见误解','Identify a common misconception')}</h3><p>${esc(content(l.misconception))}</p><h3>${esc(t('labs'))}</h3><div class="insight">${esc(content(l.practice))}</div><p class="note">${t('prerequisites')}: ${l.prerequisites.length?l.prerequisites.map(id=>{const a=D.lessons.find(q=>q.id===id);return `<a href="#learn/${id}">${esc(local(a.title))}</a>`;}).join(' · '):x('可直接开始','Begin here')}</p><h3>${esc(t('quiz'))}</h3><form id="quiz-form" data-id="${l.id}"><p>${esc(content(l.quiz.question))}</p>${content(l.quiz.options).map((v,i)=>`<label class="quiz-option"><input type="radio" name="answer" value="${i}" required><span>${esc(v)}</span></label>`).join('')}<div class="row" style="margin-top:16px"><button class="primary" type="submit">${esc(t('check'))}</button>${button(esc(t('reading'))+' ✓','read','',`data-id="${l.id}"`)}</div></form><div id="quiz-result" class="quiz-result"></div><h3>${x('从这个方法进入仓库','Project bridges')}</h3>${l.repositories.map(name=>repoMini(name)).join('')}<div class="intro-source">${t('report')}: ${l.slides.map(n=>`<a href="#library/report/${n}">${n}</a>`).join(' · ')}<br>${refs([...new Set(l.slides.flatMap(n=>D.slides.find(s=>s.n===n)?.refs||[]))])}</div></article></div><section class="card section-space"><div class="section-head"><h3>${esc(t('glossary'))}</h3>${pill('D · I · K · W · P')}</div><div class="grid four">${['data','information','knowledge','wisdom','purpose'].map(k=>`<div><div class="glossaryword">${esc(t(k))}</div><p class="smalltext muted">${esc(D.locales.en[k])}<br>${esc(D.locales.zh[k])}</p></div>`).join('')}</div><p class="note">${x('各语言标签与同一规范概念ID关联，避免把翻译差异误认为技术差异。语言包可由师生继续审校。','Every label maps to the same canonical concept ID. Language packs are open for review and improvement by students and teachers.')}</p></section>`;}
function repoMini(name){const r=D.catalog.repositories.find(r=>r.name===name);return r?`<div class="source-item row between"><span class="mono smalltext">${esc(name)}</span><span class="row"><a href="${r.url}" target="_blank" rel="noopener noreferrer">${t('source')} ↗</a>${button(selected.includes(name)?t('remove'):t('add'),'select','small',`data-name="${esc(name)}"`)}</span></div>`:'';}
function repoCard(r){return `<article class="card repository"><div class="row between">${pill(r.featured?t('featured'):x('目录入口','Catalogue'),r.featured?'':'neutral')}<span class="score">${r.score}<small class="muted"> /100</small></span></div><h3 class="mono" style="margin-top:13px">${esc(r.name)}</h3><p class="desc">${esc(r.description)}</p>${tags(r.tags.slice(0,4))}<div class="meta">${t('license')}: ${esc(r.license||x('待核对','Not recorded'))} · ${t('level')}: ${r.difficulty}/3</div>${r.hits.length?`<p class="note">${x('匹配','Matches')}: ${r.hits.map(tagName).join(' · ')}</p>`:''}<div class="row">${button(selected.includes(r.name)?t('remove'):t('add'),'select',selected.includes(r.name)?'small primary':'small',`data-name="${esc(r.name)}"`)}${button(x('选择理由','Why this match'),'repo-detail','small',`data-name="${esc(r.name)}"`)}<a class="smalltext" href="${r.url}" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div></article>`;}
function compass(){const ranked=C.rankRepositories(repoQuery,D.catalog.repositories,D.concepts,{level:repoLevel,area:repoArea,featured:repoFeatured,licensed:repoLicensed});const tags_=C.findConcepts(repoQuery,D.concepts);return `<div class="section-title"><div class="eyebrow">REPOSITORY COMPASS · CHOOSE WITH REASONS</div><h2>${x('从你的问题，找到适合的研究入口。','Find a research entry that fits your question.')}</h2><p>${x('支持多语种概念匹配。推荐依据与能力缺口可见；热度不参与评分。','Multilingual concept matching with visible reasons and learning gaps. Popularity is not used in the score.')}</p></div><section class="card"><label for="problem-query">${t('problem')}</label><textarea id="problem-query" placeholder="${esc(x('例如：我想核对中文和越南语商品中的重量与交易目的，保留证据，再做成自己的小工具。','For example: compare quantities and purpose in Chinese and Vietnamese product records, retain evidence, and build a small tool.'))}">${esc(repoQuery)}</textarea><div class="row between" style="margin-top:12px"><div class="row"><label class="inline-check">${t('level')} <select id="repo-level"><option value="1" ${repoLevel===1?'selected':''}>1 · ${x('入门','Beginner')}</option><option value="2" ${repoLevel===2?'selected':''}>2 · ${x('已有基础','Intermediate')}</option><option value="3" ${repoLevel===3?'selected':''}>3 · ${x('研究拓展','Research')}</option></select></label></div><div class="row">${button(t('recommend')+' ↗','recommend','primary')}${button(x('生成学习路径','Build a learning route'),'route')}</div></div>${tags_.length?tags(tags_):`<p class="note">${x('输入问题后识别方法概念；未识别到概念时显示目录入口，而不假装理解。','Enter a problem to identify method concepts. When none match, the catalogue remains available without pretending to understand.')}</p>`}</section><div class="toolbar section-space"><select id="repo-area"><option value="">${t('all')}</option>${D.catalog.areas.map(a=>`<option value="${a.id}" ${repoArea===a.id?'selected':''}>${esc(local(a))}</option>`).join('')}</select><div class="filters"><label><input type="checkbox" id="featured" ${repoFeatured?'checked':''}>${t('featured')}</label><label><input type="checkbox" id="licensed" ${repoLicensed?'checked':''}>${x('已记录许可','License recorded')}</label></div><span class="smalltext muted">${ranked.length} ${x('项 · 目录快照2026-09-08','entries · snapshot 2026-09-08')}</span></div><div class="grid repo-grid">${ranked.slice(0,repoLimit).map(repoCard).join('')}</div>${ranked.length>repoLimit?`<div class="row" style="justify-content:center;margin-top:20px">${button(x('查看更多','Load more'),'more')}</div>`:''}${basket()}<p class="note section-space">${x('483条来自既有报告候选表，与作者正式目录并列。目录不等于已安装源码。需要使用代码时，由上游工具锁定提交并保留许可。','483 entries are inherited from the report candidate catalogue, alongside the author’s official directory. Code is obtained separately using the upstream tool, with pinned revisions and retained licenses.')} <a href="${D.catalog.official_directory}" target="_blank" rel="noopener noreferrer">${t('source')} ↗</a></p>`;}
function basket(){return selected.length?`<div class="basket row between"><span>${t('selected')} <b>${selected.length}/6</b> · ${x('把选择变成作品设计','Turn choices into a project design')}</span><span class="row">${button(t('compare'),'compare','small')}${button(t('studio')+' →','use-selected','small')}${button(t('reset'),'clear-selected','small')}</span></div>`:'';}
const labTitles={alignment:['跨语言语义对齐','Cross-language semantic alignment'],'three-no':['3-No观测实验','3-No observation experiment'],action:['目的与行为检查','Purpose and action checks'],purpose:['目的驱动的语义路径','Purpose-aware semantic routes']};
function labForm(name){const inp=lastRun?.lab===name?lastRun.input:C.DEFAULTS[name];if(name==='alignment')return `<div class="grid two">${['left','right'].map((side,i)=>`<section class="card inset cardsmall"><h3>${i===0?x('原始语义记录','Source meaning record'):x('对照语义记录','Comparison meaning record')}</h3><div class="labform">${['language','entity','purpose','quantity','unit','currency'].map(k=>`<label>${esc({language:t('language'),entity:x('实体ID','Entity ID'),purpose:t('purpose'),quantity:x('数量','Quantity'),unit:x('单位','Unit'),currency:x('币种','Currency')}[k])}<input data-labfield="${side}.${k}" ${k==='quantity'?'type="number" step="any"':'type="text"'} value="${esc(inp[side][k]??'')}"></label>`).join('')}</div></section>`).join('')}</div>`;
if(name==='action')return `<div class="formgrid">${['purpose','observed_purpose'].map(k=>`<label>${k==='purpose'?t('purpose'):x('实际目的','Observed purpose')}<input data-labfield="${k}" value="${esc(inp[k])}"></label>`).join('')}<label>${x('计划动作','Proposed action')}<select data-labfield="action">${['draft','summarize','send','publish'].map(a=>`<option ${a===inp.action?'selected':''}>${a}</option>`).join('')}</select></label><label>${x('证据条目数量','Evidence items')}<input type="number" min="0" data-labfield="evidence_count" value="${inp.evidence_count}"></label><div class="full"><label>${x('明确允许的操作','Explicitly permitted operations')}</label><div class="row">${['draft','summarize','send','publish'].map(a=>`<label class="inline-check"><input type="checkbox" data-allow="${a}" ${inp.allowed_actions.includes(a)?'checked':''}>${a}</label>`).join('')}</div></div></div>`;
if(name==='purpose')return `<div class="formgrid"><label>${x('起点','Start')}<select data-labfield="from">${'DIKWP'.split('').map(k=>`<option ${k===inp.from?'selected':''}>${k}</option>`).join('')}</select></label><label>${x('终点','Destination')}<select data-labfield="to">${'DIKWP'.split('').map(k=>`<option ${k===inp.to?'selected':''}>${k}</option>`).join('')}</select></label><label>${t('purpose')}<select data-labfield="goal">${[['understand',x('以理解为目的','Understanding')],['speed',x('以速度为目的','Speed')],['verify',x('以保真检查为目的','Fidelity checks')]].map(([k,v])=>`<option value="${k}" ${k===inp.goal?'selected':''}>${v}</option>`).join('')}</select></label></div>`;
return `<div class="row" style="margin-bottom:12px">${button(x('冲突与缺失','Conflict + missing'),'lab-example','small','data-example="conflict"')}${button(x('一致观测','Consistent observations'),'lab-example','small','data-example="consistent"')}${button(x('全部缺失','All observations missing'),'lab-example','small','data-example="missing"')}</div><label>${x('观测区间与目标范围（°C）','Observation intervals and target (°C)')}</label><textarea id="lab-json" class="code" spellcheck="false">${esc(JSON.stringify(inp,null,2))}</textarea>`;}
function labInput(){if(activeLab==='three-no')return JSON.parse($('#lab-json').value);let v=C.clone(C.DEFAULTS[activeLab]);$$('[data-labfield]').forEach(el=>{const path=el.dataset.labfield.split('.');let obj=v;for(const k of path.slice(0,-1))obj=obj[k];obj[path.at(-1)]=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;});if(activeLab==='action')v.allowed_actions=$$('[data-allow]:checked').map(el=>el.dataset.allow);return v;}
function statusLabel(s){const labels={'equivalent':['语义等价','Equivalent'],'mismatch':['存在关键差异','Critical mismatch'],'unresolved':['需要补充解释','Unresolved'],'conflict':['观测冲突','Conflicting observations'],'incomplete':['信息不完备','Incomplete'],'insufficient':['信息不足','Insufficient'],'within-target':['支持目标范围','Within target'],'outside-target':['目标范围之外','Outside target'],'uncertain':['区间尚不确定','Uncertain interval'],'allow':['该教学条件下可继续','Allowed in this teaching case'],'review':['需澄清或选择替代动作','Review or choose a helpful alternative']};return s?x(...(labels[s]||[s,s])):'';}
function labResult(){if(!lastRun||lastRun.lab!==activeLab)return `<div class="empty">${x('运行一个实验，让方法产生看得见的差异。','Run an experiment to make the method’s effect visible.')}</div>`;const o=lastRun.output;
const summary=r=>r.chosen?`<div class="result-banner">${esc(r.chosen.path.join(' → '))}</div><p>${x('路径成本','Path cost')}: ${r.chosen.cost} · ${x('示例语义损失','Illustrative semantic loss')}: ${r.chosen.risk}</p>`:`<div class="result-banner ${['mismatch','conflict'].includes(r.status)?'bad':['review','unresolved','incomplete','uncertain','insufficient'].includes(r.status)?'warn':''}">${esc(statusLabel(r.status)||x('没有可用路径','No path'))}</div>`;
return `<div class="grid two"><div class="card inset"><h3>${t('baseline')}</h3>${summary(o.baseline)}<pre>${esc(JSON.stringify(o.baseline,null,2))}</pre></div><div class="card inset"><h3>${t('variant')}</h3>${summary(o.revision)}<pre>${esc(JSON.stringify(o.revision,null,2))}</pre></div></div><h3 style="margin-top:22px">${t('explanation')} · ${x('计算轨迹','Computation trace')}</h3><div class="tablewrap"><table class="diff-table"><thead><tr><th>${x('环节','Step')}</th><th>${x('记录','Record')}</th></tr></thead><tbody>${o.trace.map(r=>`<tr><td>${esc(r.step)}</td><td>${esc(r.detail||JSON.stringify(r))}</td></tr>`).join('')}</tbody></table></div><div class="row" style="margin-top:18px">${button(x('保存到我的作品','Attach to my project'),'attach-run','primary')}${button(x('导出实验记录','Export experiment'),'export-run')}${activeLab==='alignment'||activeLab==='action'?button(x('消融：移除目的检查','Ablation: remove purpose check'),'ablation'):''}</div><div class="note">${x('本实验由平台新编的确定性教学内核执行；输入、规则与输出均可检查。不是调用原仓库运行时的结果。','This experiment runs the platform’s new deterministic teaching core, with inspectable inputs, rules and outputs. It is not an execution of the original upstream runtime.')}</div>`;}
function labs(name){activeLab=labTitles[name]?name:activeLab;return `<div class="section-title"><div class="eyebrow">PRACTICE LABS · CHANGE ONE THING, SEE WHAT CHANGES</div><h2>${t('labs')}</h2><p>${x('不只读概念。改输入、改条件，比较基线与新机制，再把实验记录带进自己的作品。','Do more than read concepts. Change inputs and conditions, compare a baseline and a new mechanism, then attach the record to your project.')}</p></div><div class="tabs">${Object.entries(labTitles).map(([k,v])=>button(x(...v),'lab-tab',k===activeLab?'active':'',`data-id="${k}"`)).join('')}</div><section class="card"><div class="section-head"><h3>${x(...labTitles[activeLab])}</h3>${pill('LOCAL · DETERMINISTIC')}</div>${labForm(activeLab)}<div class="row" style="margin-top:20px">${button(t('run')+' ↗','run-lab','primary')}${button(t('reset'),'reset-lab')}</div></section><section class="card section-space"><h3>${t('results')}</h3><div id="lab-results">${labResult()}</div></section>`;}
function field(k,full=false){const label={problem:t('problem'),title:t('title'),beneficiary:t('beneficiary'),constraints:t('constraints'),inherited:t('inherited'),changed:t('changed'),hypothesis:t('hypothesis'),evidence:t('evidence'),reflection:t('reflection'),purpose:t('purpose'),data:t('data'),information:t('information'),knowledge:t('knowledge'),wisdom:t('wisdom')}[k];return `<div class="${full?'full':''}"><label for="f-${k}">${label}</label>${k==='title'?`<input id="f-${k}" data-projectfield="${k}" maxlength="200" value="${esc(project[k])}">`:`<textarea id="f-${k}" data-projectfield="${k}" maxlength="20000">${esc(project[k])}</textarea>`}</div>`;}
function syncProject(){if((location.hash.slice(1)||'home')==='studio')$$('[data-projectfield]').forEach(el=>project[el.dataset.projectfield]=el.value);project.locale=locale;project.updated_at=new Date().toISOString();}
function studio(){return `<div class="section-title"><div class="eyebrow">PROJECT STUDIO · INHERIT TO INNOVATE</div><h2>${x('把自己的问题，变成可以继续生长的作品。','Turn your question into a project others can build on.')}</h2><p>${x('记录方法选择、继承部分、改变部分与验证证据。导出可运行Python实验骨架、测试与上游来源清单。','Record method choices, inherited parts, your changes and test evidence. Export a runnable Python experiment scaffold, tests and upstream provenance.')}</p></div><div class="toolbar"><select id="project-picker"><option value="">${x('打开已保存作品','Open a saved project')}</option>${projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select>${button(t('create'),'new')}${button(t('import')+' JSON','import-project')}<input type="file" id="project-file" accept=".json,application/json" class="hidden">${user?pill(user.username+' · v'+project.version):pill(t('offline'))}</div><section class="card"><div class="formgrid">${field('title',true)}${field('problem',true)}${field('beneficiary')}${field('purpose')}${field('data')}${field('information')}${field('knowledge')}${field('wisdom')}${field('constraints',true)}</div></section><section class="card section-space"><div class="section-head"><h3>${t('selected')} · ${x('组件与方法角色','Components and method roles')}</h3>${button(t('compass')+' ↗','nav','small','data-to="compass"')}</div>${project.repositories.length?project.repositories.map((r,i)=>`<div class="source-item"><div class="row between"><a class="mono smalltext" href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(r.name)}</a>${button(t('remove'),'remove-component','small',`data-index="${i}"`)}</div><label class="note">${x('在本作品中承担的角色','Role in this project')}<input data-component="${i}" value="${esc(r.role)}" style="width:100%"></label><span class="note">${t('license')}: ${esc(r.license||x('待核对','Check upstream'))} · ${r.commit?esc(r.commit):x('上游获取工具将锁定提交版本','Upstream tool will pin the commit')}</span></div>`).join(''):`<div class="empty">${x('在仓库罗盘中选择项目，然后点击“作品工作室”。','Select repositories in the compass, then choose Project studio.')}</div>`}</section><section class="card section-space"><h3>${x('我的继承与创新','My inheritance and innovation')}</h3><div class="formgrid">${field('inherited')}${field('changed')}${field('hypothesis',true)}${field('evidence',true)}${field('reflection',true)}</div></section><section class="card section-space"><div class="section-head"><h3>${x('实验记录','Experiment records')} · ${project.runs.length}</h3>${button(t('labs')+' →','nav','small','data-to="labs"')}</div>${project.runs.length?project.runs.slice().reverse().map((r,ri)=>`<div class="source-item row between"><span>${esc(x(...(labTitles[r.lab]||[r.lab,r.lab])))}<br><small class="muted">${esc(r.at)}</small></span><span class="row">${button(x('查看与回放','Inspect & replay'),'replay','small',`data-index="${project.runs.length-1-ri}"`)}${button(t('remove'),'remove-run','small',`data-index="${project.runs.length-1-ri}"`)}</span></div>`).join(''):`<div class="empty">${x('运行实验后选择“保存到我的作品”。','Run a lab and choose Attach to my project.')}</div>`}</section><div class="basket row between"><span>${x('你的问题，你的选择，你的贡献。','Your question. Your choice. Your contribution.')}</span><div class="row">${button(t('save'),'save-project','small')}${button(t('export')+' JSON','export-project','small')}${button(x('导出可运行作品 ZIP','Export runnable ZIP'),'export-zip','small')}${user?button(x('版本历史','History'),'history','small'):''}</div></div><div class="note section-space">${x('新建代码采用Apache-2.0；上游仓库按自身许可继承。作品包不会自动下载、运行或公开发布上游代码。','New code uses Apache-2.0; upstream repositories retain their own licenses. The project export does not automatically download, execute or publish upstream code.')}</div>`;}
async function api(path,method='GET',body){if(!hasServer&&sessionReady)throw Error(x('请先运行完整包内的 python server.py，再进入本地服务地址。','Start python server.py from the full package and open its local address.'));const res=await fetch(path,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});let data;try{data=await res.json();}catch{throw Error('Server response is not JSON');}if(!res.ok)throw Error(data.error||'Request failed');return data;}
function classroom(){return `<div class="section-title"><div class="eyebrow">LEARN TOGETHER · KEEP YOUR OWN QUESTIONS</div><h2>${t('classroom')}</h2><p>${x('教师提供研究问题与反馈，学生自主选择方法和项目。只在主动提交后，作品快照才对课程教师可见。','Teachers provide research questions and feedback; students choose methods and projects. A project snapshot becomes visible to the course teacher only after an explicit submission.')}</p></div>${!hasServer?`<div class="callout">${x('当前为离线学习版。完整源码包中运行','You are using the offline learning edition. In the full source package run')} <code>python server.py</code>，${x('打开本地地址即可使用账户、课程与教师反馈。无需模型密钥。','then open the local address to use accounts, courses and feedback. No model key is required.')}</div>`:''}${!user?`<section class="card account-panel"><form id="auth-form"><div class="formgrid"><label>${t('username')}<input id="username" autocomplete="username" required pattern="[A-Za-z0-9_-]{3,40}"></label><label>${t('password')}<input id="password" type="password" autocomplete="current-password" required minlength="10"></label></div><div class="row" style="margin-top:16px"><button class="primary" type="submit" ${!hasServer?'disabled':''}>${t('login')}</button>${button(t('register'),'register','',!hasServer?'disabled':'')}</div><p class="note">${x('可用化名。学生自助注册；教师账号由本机管理员使用create-teacher命令创建。','Pseudonyms are supported. Self-registration creates students; the local operator provisions teachers with create-teacher.')}</p></form></section>`:`<div class="row between"><span>${pill(user.username)} ${pill(user.role)}</span>${button(t('logout'),'logout','small')}</div><div class="grid two section-space"><section class="card"><h3>${t('join')}</h3><form id="join-form"><label>${t('code')}<input id="join-code" required maxlength="20"></label><button type="submit" class="primary">${t('join')}</button></form></section>${user.role==='teacher'?`<section class="card"><h3>${t('create')} ${t('course')}</h3><form id="course-form"><label>${t('title')}<input id="course-name" maxlength="160" required></label><label>${x('课程问题与邀请','Research question and invitation')}<textarea id="course-brief"></textarea></label><button class="primary" type="submit">${t('create')}</button></form></section>`:`<section class="card"><h3>${x('带着自己的问题参与','Participate with your own question')}</h3><p>${x('先在作品工作室保存作品，再选择课程提交。其他学生不能浏览你的私人草稿。','Save your work in the project studio, then submit it to a chosen course. Other students cannot browse your private drafts.')}</p>${button(t('studio')+' →','nav','small','data-to="studio"')}</section>`}</div><div class="section-head section-space"><h3>${t('course')}</h3>${button(x('刷新','Refresh'),'refresh-courses','small')}</div><div id="course-list">${courseList()}</div>`}`;}
function courseList(){return classCourses.length?classCourses.map(c=>`<section class="card course"><div class="row between"><h3>${esc(c.name)}</h3>${pill(t('code')+': '+c.code)}</div><p>${esc(c.brief)}</p><div class="row">${button(x('查看作品与反馈','View submissions & feedback'),'load-submissions','small',`data-id="${c.id}"`)}${button(t('submit'),'submit-project','small primary',`data-id="${c.id}"`)}</div>${submissions[c.id]?`<div class="section-space">${submissions[c.id].map(s=>`<article class="source-item"><div class="row between"><strong>${esc(s.snapshot.title)}</strong><small>${esc(s.username)} · v${s.version}</small></div><p class="smalltext">${esc(s.snapshot.problem)}</p>${button(x('阅读完整作品','Read full project'),'view-submission','small',`data-id="${s.id}" data-course="${c.id}"`)}${s.feedback?`<div class="insight" style="margin-top:12px"><strong>${t('feedback')}</strong><p>${esc(s.feedback.comment)}</p><small>${esc(JSON.stringify(s.feedback.rubric))}</small></div>`:''}${user.id===c.teacher_id?`<form class="review-form" data-id="${s.id}" data-course="${c.id}" style="margin-top:14px"><label>${t('feedback')}<textarea name="comment" required placeholder="${esc(x('理解、选择、继承、验证、创新：哪些地方值得肯定，哪个问题值得继续研究？','Understanding, choice, inheritance, validation, innovation: what deserves recognition and what should be explored next?'))}">${esc(s.feedback?.comment||'')}</textarea></label><button class="small primary" type="submit">${t('save')} ${t('feedback')}</button></form>`:''}</article>`).join('')||`<p class="muted">${t('empty')}</p>`}</div>`:''}</section>`).join(''):`<div class="empty">${t('empty')}</div>`;}
function library(part,num){if(part==='report'){const s=D.slides.find(s=>s.n===Number(num))||D.slides[0];return `<div class="section-title"><div class="eyebrow">LECTURE ↔ METHOD ↔ PROJECT</div><h2>${t('report')}</h2><div class="row"><select id="slide-picker">${D.slides.map(a=>`<option value="${a.n}" ${a.n===s.n?'selected':''}>${String(a.n).padStart(3,'0')} · ${esc(a.title)}</option>`).join('')}</select>${button(t('library'),'nav','small','data-to="library"')}</div></div><article class="card library-report"><div class="eyebrow">${String(s.n).padStart(3,'0')} / 128 · ${esc(s.tag)}</div><h2>${esc(s.title)}</h2><h3>${esc(s.thesis)}</h3><div class="tags">${(s.items||[]).map(v=>pill(v)).join('')}</div><p class="report-notes">${esc(s.notes)}</p>${s.reading_question?`<div class="insight">${esc(s.reading_question)}</div>`:''}<div class="intro-source">${refs(s.refs||[])}</div><div class="row" style="margin-top:24px">${button(t('back'),'slide','small',`data-n="${Math.max(1,s.n-1)}"`)}${button(t('next'),'slide','small',`data-n="${Math.min(128,s.n+1)}"`)}${button(t('learn'),'nav','primary small','data-to="learn"')}</div></article>`;}
const q=C.norm(libraryQuery);const items=D.sources.filter(s=>C.norm(JSON.stringify(s)).includes(q));return `<div class="section-title"><div class="eyebrow">RESEARCH LIBRARY · FOLLOW THE ORIGINAL SOURCE</div><h2>${t('library')}</h2><p>${x('从论文、正式图书、企业技术文本与学术共同体，回到方法的来源与研究问题。','Explore papers, published books, technical records and research communities, then return to the methods and questions behind them.')}</p></div><div class="toolbar"><input id="library-search" value="${esc(libraryQuery)}" placeholder="${esc(t('search'))}">${button(t('search'),'search-library','primary')}${button(t('report')+' ↗','report')}</div><div class="tabs">${[['sources',x('全部来源','All sources')],['books',x('正式图书','Published books')],['lecture',x('报告联动','Lecture bridges')]].map(([k,v])=>button(v,'library-tab',libraryTab===k?'active':'',`data-id="${k}"`)).join('')}</div>${libraryTab==='books'?booksHtml():libraryTab==='lecture'?`<div class="grid three">${D.lessons.map(l=>`<article class="card"><h3>${esc(local(l.title))}</h3><p class="smalltext muted">${esc(content(l.question))}</p><div class="row">${l.slides.map(n=>`<a href="#library/report/${n}" class="pill">${t('report')} ${n}</a>`).join('')}</div><div style="margin-top:16px">${button(t('learn')+' →','lesson','small',`data-id="${l.id}"`)}</div></article>`).join('')}</div>`:`<p class="note">${items.length} ${x('条来源记录；核验日期与资料类型分别保留。','source entries; dates and evidence types are retained.')}</p><div class="source-list">${items.map(s=>`<article class="source-item"><div class="row between">${pill(s.id)}<small class="muted">${esc(s.kind||'')}</small></div><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p class="note">${esc(s.position||'')} ${s.date?' · '+esc(s.date):''}</p><details><summary class="smalltext muted">${x('来源记录','Provenance record')}</summary><p class="note">${esc(s.status||'')} · ${esc(s.checked||'')}</p></details></article>`).join('')}</div>`}`;}
function booksHtml(){const a=Array.isArray(D.research.books)?D.research.books:Object.values(D.research.books).flat().filter(x=>x&&typeof x==='object');return `<div class="grid three">${a.map(b=>`<article class="card"><div class="book"><div class="eyebrow" style="color:#e4ca92">YUCONG DUAN · RESEARCH</div><h3>${esc(b.title||b.name||b.title_zh||'')}</h3><p>${esc(b.publisher||'')} ${esc(b.year||'')}</p></div><p class="note">${esc(b.isbn||b.ISBN||'')}</p>${(b.url||D.sources.find(s=>s.id===b.ref)?.url)?`<a href="${esc(safeUrl(b.url||D.sources.find(s=>s.id===b.ref)?.url))}" target="_blank" rel="noopener noreferrer">${t('source')} ↗</a>`:''}<p class="smalltext">${esc(b.connection||b.note||b.theme||b.domain||'')}</p></article>`).join('')}</div>`;}
let modalOpener=null;
function modal(html){modalOpener=document.activeElement;$('#modal').innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modalbox">${button('×','close-modal','close','aria-label="Close"')}${html}</div></div>`;$('#modal button')?.focus();}
function closeModal(){const had=$('#modal').innerHTML!=='';$('#modal').innerHTML='';if(had&&modalOpener?.isConnected)modalOpener.focus();modalOpener=null;}
function download(name,data,type='application/json'){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function selectRepo(name){closeModal();if(selected.includes(name))selected=selected.filter(x=>x!==name);else{if(selected.length>=6)throw Error(x('一次最多选择6个仓库，便于比较与明确接口。','Choose at most six repositories so roles and interfaces remain clear.'));selected.push(name);}persist();render();}
function toComponents(){return selected.map(name=>{const r=D.catalog.repositories.find(r=>r.name===name);return {name:r.name,url:r.url,license:r.license,role:r.role||'',commit:null};});}
async function saveProject(){syncProject();project=C.validateProject(project);if(user&&hasServer){const r=await api('/api/projects/'+project.id,'PUT',project);project=r.project;}const idx=projects.findIndex(p=>p.id===project.id);if(idx>=0)projects[idx]=C.clone(project);else projects.unshift(C.clone(project));const stored=persist();if(!stored&&!user)throw Error(x('浏览器未能保存，请立即导出作品。','Browser storage failed; export your project now.'));toast(t('saved'));return project;}
function compareModal(){const rows=selected.map(name=>D.catalog.repositories.find(r=>r.name===name));modal(`<h2>${t('compare')}</h2><div class="tablewrap"><table class="diff-table"><thead><tr><th>${x('候选','Candidate')}</th><th>${x('作用与能力','Role & concepts')}</th><th>${t('license')}</th><th>${x('继承思考','Adaptation question')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mono">${esc(r.name)}</td><td>${esc(r.role)}${tags(r.tags)}</td><td>${esc(r.license||x('待核对','Check source'))}</td><td>${esc(r.explore||x('先核对输入输出与原始运行方式，再定义本作品接口。','Inspect inputs, outputs and original execution before defining the project interface.'))}</td></tr>`).join('')}</tbody></table></div><p class="note">${x('组合表达互补研究角色；接口兼容性仍需在作品中具体实现和测试。','A combination expresses complementary research roles. Interface compatibility is established by the adapters and tests in your project.')}</p>${button(t('studio')+' →','use-selected','primary')}`);}
function render(){const parts=location.hash.slice(1).split('/');const page=parts[0]||'home';$('#app').innerHTML=header();const views={home:()=>home(),learn:()=>learn(parts[1]),compass:()=>compass(),labs:()=>labs(parts[1]),studio:()=>studio(),classroom:()=>classroom(),library:()=>library(parts[1],parts[2])};$('#main').innerHTML=(views[page]||views.home)()+footer();document.documentElement.lang=locale;document.title=(locale==='zh'?'知行共创':'DIKWP OpenStudio')+' · '+(t(page)||'');}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;ev.preventDefault();try{const act=b.dataset.action;if(act==='nav'){syncProject();persist();go(b.dataset.to);}else if(act==='lesson')go('learn/'+b.dataset.id);else if(act==='scenario'){const s=D.scenarios.find(s=>s.id===b.dataset.id);project=C.newProject();project.title=local(s.title);project.problem=local(s.problem);project.purpose=local(s.problem);project.locale=locale;selected=s.repos.filter(n=>D.catalog.repositories.some(r=>r.name===n));project.repositories=toComponents();repoQuery=local(s.problem);activeLab=s.lab;lastRun=null;persist();go('studio');}
else if(act==='recommend'){repoQuery=$('#problem-query').value;repoLevel=Number($('#repo-level').value);repoLimit=24;render();}
else if(act==='route'){repoQuery=$('#problem-query').value;const tags=C.findConcepts(repoQuery,D.concepts),route=C.learningRoute(D.lessons,tags,progress.quizzes);modal(`<h2>${t('recommend')}</h2><p class="muted">${esc(repoQuery)}</p><div class="source-list">${route.map((l,i)=>`<div class="source-item row between"><span>${i+1}. ${esc(local(l.title))} ${l.passed?'✓':''}</span>${button(t('learn'),'lesson','small',`data-id="${l.id}"`)}</div>`).join('')}</div><p class="note">${x('路径按概念与前置关系生成，无预设天数。可以直接进入任意单元。','Routes follow concepts and prerequisites without fixed deadlines. Every module remains directly accessible.')}</p>`);}
else if(act==='select')selectRepo(b.dataset.name);else if(act==='compare')compareModal();else if(act==='clear-selected'){selected=[];persist();render();}else if(act==='use-selected'){syncProject();project.repositories=toComponents();persist();go('studio');}
else if(act==='repo-detail'){const r=C.rankRepositories(repoQuery,D.catalog.repositories,D.concepts,{level:repoLevel}).find(r=>r.name===b.dataset.name);modal(`<h2 class="mono" style="overflow-wrap:anywhere">${esc(r.name)}</h2><p>${esc(r.description)}</p>${tags(r.tags)}<h3>${x('为什么推荐','Why this match')}</h3><p>${x('概念匹配','Concept matches')}: ${r.hits.map(tagName).join(' · ')||'—'}<br>${x('目录精选','Curated entry')}: ${r.featured?'✓':'—'}<br>${x('学习基础匹配','Experience fit')}: ${r.reasons.experience?'✓':x('需要补充基础','Additional foundations suggested')}</p><p>${esc(r.explore||'')}</p><div class="callout">${x('匹配公式：概念覆盖65%、文本匹配15%、精选入口10%、基础匹配10%；精确仓库名额外优先。不是科学价值或实际效果排名。','Fit: 65% concept coverage, 15% lexical match, 10% curated entry, 10% experience fit; exact repository names receive a bonus. This is not a scientific-merit or performance ranking.')}</div><div class="row"><a href="${r.url}" target="_blank" rel="noopener noreferrer">GitHub ↗</a>${button(t('add'),'select','primary',`data-name="${esc(r.name)}"`)}</div>`);}
else if(act==='more'){repoLimit+=24;render();}else if(act==='read'){progress.readings[b.dataset.id]=new Date().toISOString();persist();toast(t('saved'));}
else if(act==='lab-tab'){lastRun=null;go('labs/'+b.dataset.id);}else if(act==='run-lab'){const input=labInput(),output=C.runLab(activeLab,input);lastRun={lab:activeLab,input,output,at:new Date().toISOString(),engine:C.VERSION};$('#lab-results').innerHTML=labResult();}
else if(act==='reset-lab'){lastRun=null;render();}else if(act==='lab-example'){const input=C.clone(C.DEFAULTS['three-no']);if(b.dataset.example==='consistent')input.observations=[{name:'A',low:2,high:4},{name:'B',low:3,high:5}];if(b.dataset.example==='missing')input.observations=[{name:'A',low:null,high:null}];$('#lab-json').value=JSON.stringify(input,null,2);}
else if(act==='attach-run'){if(!lastRun)throw Error('Run an experiment first');if(project.runs.length>=100)throw Error('Experiment history is full');project.runs.push(C.clone(lastRun));persist();toast(x('实验输入与结果已加入当前作品。','The input and result have been attached to your current project.'));}
else if(act==='export-run'){if(lastRun)download('experiment-'+lastRun.lab+'.json',JSON.stringify(lastRun,null,2));}
else if(act==='ablation'){const output=C.runLab(activeLab,lastRun.input,{ignorePurpose:true});modal(`<h2>${x('消融：只移除目的检查','Ablation: remove only the purpose check')}</h2><div class="grid two"><div><h3>${x('完整机制','Full mechanism')}</h3><pre>${esc(JSON.stringify(lastRun.output.revision,null,2))}</pre></div><div><h3>${x('消融机制','Ablated mechanism')}</h3><pre>${esc(JSON.stringify(output.revision,null,2))}</pre></div></div><p>${x('目的相同的样例未必出现差异。把两侧Purpose改为不同值，再观察消融的后果。','A case with matching purposes may not change. Set different purposes, then inspect the effect of the ablation.')}</p>`);}
else if(act==='new'){syncProject();if(project.title){try{const p=C.validateProject(project);const i=projects.findIndex(v=>v.id===p.id);if(i>=0)projects[i]=p;else projects.unshift(p);}catch{}}project=C.newProject();project.locale=locale;persist();go('studio');}
else if(act==='save-project'){await saveProject();render();}else if(act==='export-project'){syncProject();download('openstudio-project.json',JSON.stringify(C.validateProject(project),null,2));persist();}else if(act==='export-zip'){syncProject();const files=C.scaffold(project);files['LICENSE']=D.license;files['NOTICE']='New educational scaffold generated in DIKWP OpenStudio. Research foundations: Yucong Duan (段玉聪). Upstream names and licenses are retained in upstream.lock.json.\n';download('openstudio-project-'+project.id+'.zip',C.zipFiles(files),'application/zip');persist();toast(x('可运行作品包已生成。','Runnable project package generated.'));}
else if(act==='import-project')$('#project-file').click();else if(act==='remove-component'){syncProject();project.repositories.splice(Number(b.dataset.index),1);persist();render();}else if(act==='remove-run'){syncProject();project.runs.splice(Number(b.dataset.index),1);persist();render();}
else if(act==='replay'){syncProject();const r=project.runs[Number(b.dataset.index)],out=C.runLab(r.lab,r.input);modal(`<h2>${x('回放与一致性检查','Replay and consistency check')}</h2><div class="result-banner">${JSON.stringify(out)===JSON.stringify(r.output)?x('当前内核回放与保存结果一致','Current-core replay matches the saved result'):x('输出不同：请比较内核版本或原记录','Output differs: compare engine versions or the stored record')}</div><pre>${esc(JSON.stringify({input:r.input,saved:r.output,replayed:out},null,2))}</pre>`);}
else if(act==='history'){syncProject();const d=await api('/api/projects/'+project.id+'/history');modal(`<h2>${x('服务器版本历史','Server version history')}</h2>${d.revisions.map(r=>`<details class="source-item"><summary>v${r.version} · ${esc(r.created)}</summary><pre>${esc(JSON.stringify(r.project,null,2))}</pre></details>`).join('')}`);}
else if(act==='register'){await api('/api/register','POST',{username:$('#username').value,password:$('#password').value});toast(x('学生账号已创建，请登录。','Student account created. Please sign in.'));}
else if(act==='logout'){await api('/api/logout','POST',{});user=null;csrf=null;restore();classCourses=[];submissions={};render();}
else if(act==='refresh-courses'){await refreshCourses();render();}else if(act==='load-submissions'){const r=await api('/api/courses/'+b.dataset.id+'/submissions');submissions[b.dataset.id]=r.submissions;render();}
else if(act==='submit-project'){await saveProject();await api('/api/courses/'+b.dataset.id+'/submit','POST',{project_id:project.id});submissions[b.dataset.id]=(await api('/api/courses/'+b.dataset.id+'/submissions')).submissions;render();toast(t('saved'));}
else if(act==='view-submission'){const s=submissions[b.dataset.course].find(s=>s.id===b.dataset.id);modal(`<h2>${esc(s.snapshot.title)}</h2><pre>${esc(C.projectMarkdown(s.snapshot))}</pre>`);}
else if(act==='report')go('library/report/1');else if(act==='slide')go('library/report/'+b.dataset.n);else if(act==='search-library'){libraryQuery=$('#library-search').value;render();}else if(act==='library-tab'){libraryTab=b.dataset.id;render();}else if(act==='close-modal')closeModal();
}catch(error){toast(error.message||t('error'),true);}});
document.addEventListener('change',async e=>{try{if(e.target.id==='locale'){syncProject();locale=e.target.value;writeStore('openstudio:language',locale);reading=['zh','vi'].includes(locale)?locale:'en';writeStore('openstudio:reading',reading);persist();render();}else if(e.target.id==='reading'){reading=e.target.value;writeStore('openstudio:reading',reading);render();}else if(e.target.id==='repo-area'){repoArea=e.target.value;repoQuery=$('#problem-query').value;render();}else if(e.target.id==='featured'){repoFeatured=e.target.checked;repoQuery=$('#problem-query').value;render();}else if(e.target.id==='licensed'){repoLicensed=e.target.checked;repoQuery=$('#problem-query').value;render();}else if(e.target.id==='repo-level'){repoLevel=Number(e.target.value);}else if(e.target.id==='project-picker'&&e.target.value){project=C.clone(projects.find(p=>p.id===e.target.value));persist();render();}else if(e.target.dataset.component!==undefined){project.repositories[Number(e.target.dataset.component)].role=e.target.value;persist();}else if(e.target.id==='project-file'){const f=e.target.files[0];if(!f)return;if(f.size>700000)throw Error('Project file too large');const p=C.validateProject(JSON.parse(await f.text()));p.version=0;p.id=C.newProject().id;project=p;persist();render();toast(t('saved'));}else if(e.target.id==='slide-picker')go('library/report/'+e.target.value);}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{if(e.target.dataset.projectfield){project[e.target.dataset.projectfield]=e.target.value;persist();}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='quiz-form'){const l=D.lessons.find(l=>l.id===e.target.dataset.id),val=new FormData(e.target).get('answer');if(val===null)throw Error(x('请选择一个答案。','Choose an answer.'));const r=C.checkQuiz(l,Number(val));progress.quizzes[l.id]={answer:r.answer,correct:r.correct,at:new Date().toISOString()};persist();$('#quiz-result').innerHTML=`<div class="${r.correct?'insight':'example'}"><strong>${r.correct?x('本次自测正确','Correct for this self-check'):x('再想一想','Think it through')}</strong><p>${esc(content(r.explanation))}</p></div>`;}
else if(e.target.id==='auth-form'){const r=await api('/api/login','POST',{username:$('#username').value,password:$('#password').value});user=r.user;csrf=r.csrf;restore();projects=(await api('/api/projects')).projects;await refreshCourses();persist();render();}
else if(e.target.id==='join-form'){await api('/api/courses/join','POST',{code:$('#join-code').value});await refreshCourses();render();}
else if(e.target.id==='course-form'){await api('/api/courses','POST',{name:$('#course-name').value,brief:$('#course-brief').value});await refreshCourses();render();}
else if(e.target.classList.contains('review-form')){const fd=new FormData(e.target);await api('/api/submissions/'+e.target.dataset.id+'/review','POST',{comment:fd.get('comment'),rubric:{}});submissions[e.target.dataset.course]=(await api('/api/courses/'+e.target.dataset.course+'/submissions')).submissions;render();toast(t('saved'));}
}catch(err){toast(err.message,true);}});
async function refreshCourses(){if(user)classCourses=(await api('/api/courses')).courses;}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
async function boot(){restore();render();if(location.protocol==='http:'||location.protocol==='https:'){try{hasServer=true;const r=await api('/api/session');user=r.user;csrf=r.csrf;if(user){restore();projects=(await api('/api/projects')).projects;await refreshCourses();}}catch{hasServer=false;}}sessionReady=true;render();}
boot();

document.getElementById('skip-main').addEventListener('click',e=>{e.preventDefault();document.getElementById('main').focus();});
